        m1 = n + 1
        if m1 <= N:
            moves.append(m1)

        m2 = 2 * n
        if m2 <= N:
            moves.append(m2)

        is_winning = False

        for m in moves:
            if m == N:
                # Instant win (The player at n moves to N)
                is_winning = True
                break

            # m < N. We check P[m]. Since we are iterating backwards, P[m] must be calculated.
            if m in P:
                # If m is a Losing position (P[m] is False), then n is a Winning position.
                if not P[m]:
