def solve_game_type(N):
    # W[n] = True if position n is an N-position (Winning for the current player), 
    # False if it is a P-position (Losing for the current player).
    # We only need to store up to N.
    W = {} 

    # Iterate backwards from N-1 down to 1
    for n in range(N - 1, 0, -1):
        can_win = False

        # Check move to n + 1
        next_n_plus_1 = n + 1
        if next_n_plus_1 <= N:
            if next_n_plus_1 == N:
                # Move to N wins immediately
                can_win = True
            elif next_n_plus_1 in W:
                # Move to a P-position (where opponent loses)
                if W[next_n_plus_1] == False:
                    can_win = True

        # If already found a winning move, no need to check 2n
        if can_win:
            W[n] = True
            continue

        # Check move to 2n
        next_n_times_2 = 2 * n
        if next_n_times_2 <= N:
            if next_n_times_2 == N:
                # Move to N wins immediately
                can_win = True
            elif next_n_times_2 in W:
                # Move to a P-position (where opponent loses)
                if W[next_n_times_2] == False:
                    can_win = True

        W[n] = can_win

    # The game is Type A if W[1] is True, Type B if W[1] is False
    return "Type A" if W.get(1, False) else "Type B"

# Task 1: Calculate types for N from 400 to 420
